() => {
  const inputs = Array.from(document.querySelectorAll('input'));
  const setVal = (el, v) => {
    const proto = Object.getPrototypeOf(el);
    const desc = Object.getOwnPropertyDescriptor(proto, 'value');
    desc.set.call(el, v);
    el.dispatchEvent(new Event('input', { bubbles: true }));
    el.dispatchEvent(new Event('change', { bubbles: true }));
  };
  const user = inputs.find(i => (i.placeholder||'').includes('用户名'));
  const pass = inputs.find(i => (i.placeholder||'').includes('密码') || i.type === 'password');
  if (user) setVal(user, 'admin');
  if (pass) setVal(pass, 'admin123');
  return { found: { user: !!user, pass: !!pass }, userVal: user?.value, passVal: pass?.value };
}

