() => {
  // find the export approval panel's "显示已处理" checkbox (the second one)
  const labels = Array.from(document.querySelectorAll('label'));
  const results = [];
  labels.forEach((l, i) => {
    if (l.textContent.includes('显示已处理')) {
      const cb = l.querySelector('input[type=checkbox]');
      results.push({ i, checked: cb?.checked });
    }
  });
  // click the second one (export panel)
  const target = labels.filter(l => l.textContent.includes('显示已处理'))[1];
  if (target) {
    const cb = target.querySelector('input[type=checkbox]');
    if (cb && !cb.checked) cb.click();
    return { clicked: true, results };
  }
  return { clicked: false, results };
}

